<script setup lang="ts">import type{Application,ApplicationStage}from'@career-launch/shared';import{StatusBadge}from'@career-launch/ui';import{computed,onMounted,ref}from'vue';import{repository}from'../../services/repository';import{canTransition,stageMeta}from'./stages';const items=ref<Application[]>([]);const view=ref<'board'|'list'>('board');const selected=ref<Application|null>(null);const stages=Object.keys(stageMeta)as ApplicationStage[];const grouped=computed(()=>Object.fromEntries(stages.map(stage=>[stage,items.value.filter(item=>item.stage===stage)]))as Record<ApplicationStage,Application[]>);async function load(){items.value=await repository.applications.list()}async function change(item:Application,event:Event){const next=(event.target as HTMLSelectElement).value as ApplicationStage;if(!canTransition(item.stage,next))return;await repository.applications.updateStage(item.id,next);await load();selected.value=items.value.find(entry=>entry.id===item.id)??null}onMounted(load)</script>
<template><section><header class="page-head"><div><h1>投递看板</h1><p>把每一次申请放在正确阶段，下一步会更清楚。</p></div><div class="view-toggle"><button :aria-pressed="view==='board'" @click="view='board'">看板</button><button :aria-pressed="view==='list'" @click="view='list'">列表</button></div></header><div class="summary"><span><b>{{items.length}}</b> 全部投递</span><span><b>{{grouped.interview.length}}</b> 面试中</span><span><b>{{grouped.offer.length}}</b> Offer</span></div><div v-if="view==='board'" class="board"><section v-for="stage in stages" :key="stage"><header><StatusBadge :tone="stageMeta[stage].tone">{{stageMeta[stage].label}}</StatusBadge><span>{{grouped[stage].length}}</span></header><button v-for="item in grouped[stage]" :key="item.id" class="application-card" @click="selected=item"><span class="logo">{{item.companyLogoText}}</span><strong>{{item.jobTitle}}</strong><small>{{item.companyName}} · {{item.city.join(' / ')}}</small><time>{{new Date(item.updatedAt).toLocaleDateString('zh-CN')}}</time></button></section></div><div v-else class="application-list cl-card"><article v-for="item in items" :key="item.id"><span class="logo">{{item.companyLogoText}}</span><div><strong>{{item.jobTitle}}</strong><small>{{item.companyName}} · {{item.city.join(' / ')}}</small></div><select :value="item.stage" aria-label="更新投递阶段" @change="change(item,$event)"><option v-for="stage in stages" :key="stage" :value="stage" :disabled="!canTransition(item.stage,stage)">{{stageMeta[stage].label}}</option></select><button class="cl-quiet-button" @click="selected=item">详情</button></article></div><div v-if="selected" class="drawer-layer" @mousedown.self="selected=null"><aside class="drawer" role="dialog" aria-modal="true" aria-label="投递详情"><button class="close" @click="selected=null">×</button><span class="logo large">{{selected.companyLogoText}}</span><h2>{{selected.jobTitle}}</h2><p>{{selected.companyName}} · {{selected.city.join(' / ')}}</p><label>当前阶段<select :value="selected.stage" @change="change(selected,$event)"><option v-for="stage in stages" :key="stage" :value="stage" :disabled="!canTransition(selected.stage,stage)">{{stageMeta[stage].label}}</option></select></label><h3>进度时间线</h3><ol><li v-for="event in selected.events" :key="event.id"><span></span><div><strong>{{stageMeta[event.toStage].label}}</strong><small>{{new Date(event.occurredAt).toLocaleString('zh-CN')}}</small><p v-if="event.note">{{event.note}}</p></div></li></ol><h3>下一步提醒</h3><div class="reminder"><input type="datetime-local" aria-label="提醒时间"/><button class="cl-quiet-button">设置提醒</button></div></aside></div></section></template>
<style scoped>.page-head{display:flex;justify-content:space-between;gap:20px}.page-head h1{margin:0;font-size:30px}.page-head p{color:var(--cl-muted)}.view-toggle{display:flex;align-self:start;padding:3px;border-radius:8px;background:var(--cl-border)}.view-toggle button{padding:6px 13px;border:0;border-radius:6px;color:var(--cl-muted);background:transparent}.view-toggle button[aria-pressed=true]{color:var(--cl-text);background:var(--cl-surface)}.summary{display:flex;gap:28px;margin:18px 0;color:var(--cl-muted)}.summary b{color:var(--cl-text-strong);font-size:22px}.board{display:grid;grid-template-columns:repeat(7,minmax(210px,1fr));gap:10px;overflow-x:auto;padding-bottom:12px}.board>section{min-height:390px;padding:11px;border-radius:10px;background:var(--cl-border)}.board>section>header{display:flex;justify-content:space-between;margin-bottom:10px}.board>section>header>span{color:var(--cl-muted)}.application-card{width:100%;display:grid;grid-template-columns:34px 1fr;gap:3px 9px;margin-bottom:8px;padding:12px;border:0;border-radius:9px;color:var(--cl-text);background:var(--cl-surface);text-align:left}.logo{width:34px;height:34px;display:grid;grid-row:span 2;place-items:center;border-radius:8px;color:var(--cl-primary);background:var(--cl-primary-soft);font-weight:800}.application-card strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.application-card small,.application-card time,.application-list small{color:var(--cl-muted);font-size:11px}.application-card time{grid-column:1/-1;margin-top:7px}.application-list article{display:grid;grid-template-columns:40px 1fr 130px auto;gap:12px;align-items:center;padding:14px 18px}.application-list article+article{border-top:1px solid var(--cl-border)}.application-list strong,.application-list small{display:block}.application-list select,.drawer select,.reminder input{height:39px;padding:0 9px;border:1px solid var(--cl-border);border-radius:7px;color:var(--cl-text);background:var(--cl-surface)}.drawer-layer{position:fixed;z-index:80;inset:0;background:rgba(8,15,29,.45)}.drawer{position:absolute;top:0;right:0;width:min(100%,430px);height:100%;overflow:auto;padding:30px;background:var(--cl-surface);box-shadow:var(--cl-shadow-float)}.close{position:absolute;top:16px;right:16px;width:36px;height:36px;border:0;border-radius:50%;background:var(--cl-canvas);font-size:22px}.logo.large{width:52px;height:52px}.drawer h2{margin:14px 0 2px}.drawer>p{color:var(--cl-muted)}.drawer label{display:grid;gap:6px;margin:20px 0}.drawer h3{margin-top:28px;font-size:16px}.drawer ol{padding:0;list-style:none}.drawer li{display:grid;grid-template-columns:12px 1fr;gap:10px;padding:8px 0}.drawer li>span{width:9px;height:9px;margin-top:7px;border-radius:50%;background:var(--cl-primary)}.drawer li small{display:block;color:var(--cl-muted)}.drawer li p{margin:4px 0}.reminder{display:flex;gap:8px}@media(max-width:650px){.page-head{flex-direction:column}.application-list article{grid-template-columns:36px 1fr}.application-list select,.application-list button{grid-column:2}.summary{flex-wrap:wrap}.drawer{padding:22px}}</style>
